using System;
using System.Text;

class Program
{
    static void Main()
    {
        string name = "Alice";
        int age = 25;
        // String interpolation
        Console.WriteLine($"User: {name}, Age: {age}");

        // StringBuilder for loops
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= 5; i++)
        {
            sb.Append(i).Append(" ");
        }
        Console.WriteLine(sb.ToString());
    }
}

