solution.cpp:
#include <iostream>
#include <string>
#include <algorithm>
using namespace std;
int main() {
    string s; if (getline(cin, s)) {
        while (!s.empty() && (s.back() == '\r' || s.back() == '\n')) s.pop_back();
        reverse(s.begin(), s.end());
        cout << s << "\n";
    }
    return 0;
}
